import Foundation
import Testing
@testable import RPlusCore

/// Node outputs for every FluidParsers function. Inputs: synthetic pastes from the Node tests
/// (recorded while the labs*.test.mjs suites ran) plus hand-written synthetic pastes.
/// Generated by scratchpad fluids-probe/gen.mjs; do not edit by hand.
@Suite("Labs Fluids extra") struct LabsFluidsExtraTests {
    struct Case: Sendable { let fn: String; let input: String; let out: String; let tNorm: String?; let priorRefs: [String: [Double]]? }

    static let cases: [Case] = {
        let arr = try! JSONSerialization.jsonObject(with: Data(raw.utf8)) as! [[String: Any]]
        return arr.map { d in
            var refs: [String: [Double]]?
            if let r = d["priorRefs"] as? [String: [Any]] { refs = r.mapValues { $0.map { ($0 as! NSNumber).doubleValue } } }
            return Case(fn: d["fn"] as! String, input: d["input"] as! String, out: d["out"] as! String,
                        tNorm: d["tNorm"] as? String, priorRefs: refs)
        }
    }()

    static func run(_ c: Case) -> String {
        switch c.fn {
        case "cito": FluidParsers.parsearCitoquimicoLiquidos(c.input)
        case "lcr": FluidParsers.parsearLCR(c.input)
        case "interp": FluidParsers.citoquimicoInterpretacionLine(c.input)
        case "blocks": String(data: try! JSONSerialization.data(withJSONObject: FluidParsers.citoquimicoBlocksNormText(c.input), options: [.withoutEscapingSlashes]), encoding: .utf8)!
        case "ego": FluidParsers.parseEGO(c.input)
        case "eu": FluidParsers.parseElectrolitosOrina(c.input)
        case "depcr": FluidParsers.parseDepuracionCreatinina(c.input)
        case "cuant": FluidParsers.parseCuantOrina(c.input)
        case "heces": FluidParsers.parseFisicoquimicoHeces(c.input)
        case "frotis": FluidParsers.parseFrotisSangre(c.input)
        case "serol": FluidParsers.parseSerologiaBancoSangre(c.input)
        case "gs": FluidParsers.parseGrupoSangreCoombs(c.input)
        case "plq": FluidParsers.parsePlaquetasCitrato(c.input, tNorm: c.tNorm ?? "", priorRefs: c.priorRefs)
        default: "?"
        }
    }

    @Test(arguments: 0..<106) func matchesNode(_ i: Int) {
        let c = Self.cases[i]
        #expect(Self.run(c) == c.out, "\(c.fn) #\(i)")
    }

    @Test func caseCount() { #expect(Self.cases.count == 106) }

